    [System.Runtime.InteropServices.DllImport("user32.dll")]static extern bool EnableWindow(IntPtr window,bool enabled);
    const BindingFlags Private=BindingFlags.NonPublic|BindingFlags.Instance;static int checks;
    static void Need(bool ok,string error){checks++;if(!ok)throw new Exception(error);}
    static bool SameRegion(Bitmap a,Bitmap b,Rectangle area){for(int y=area.Top;y<area.Bottom;y++)for(int x=area.Left;x<area.Right;x++)if(a.GetPixel(x,y)!=b.GetPixel(x,y))return false;return true;}
    static void CheckColors(PetPainter painter){
        var prefs=new PetPreferences{HubColor="#4E8FE4",CapsuleColor="#4E8FE4",RingColor="#4E8FE4"};var quota=new PetQuotaSnapshot{Short=new PetQuotaWindow{Remaining=100}};var left=new Rectangle(9,7,40,40);var middle=new Rectangle(57,8,165,37);var right=new Rectangle(228,7,40,40);
        painter.ApplyAppearance(prefs);using(var initial=painter.RenderCapsule(1,quota,"","执行/思考",false,0)){
            prefs.HubColor="#FF3333";painter.ApplyAppearance(prefs);using(var hub=painter.RenderCapsule(1,quota,"","执行/思考",false,0)){Need(!SameRegion(initial,hub,left)&&SameRegion(initial,hub,middle)&&SameRegion(initial,hub,right),"Hub button color is missing or changes another component");var color=hub.GetPixel(12,27);Need(color.R>color.B&&color.R>color.G,"Left circle is still white");}
            prefs.HubColor="#4E8FE4";prefs.CapsuleColor="#44DD88";painter.ApplyAppearance(prefs);using(var capsule=painter.RenderCapsule(1,quota,"","执行/思考",false,0))Need(SameRegion(initial,capsule,left)&&!SameRegion(initial,capsule,middle)&&SameRegion(initial,capsule,right),"Capsule color is not independent");
            prefs.CapsuleColor="#4E8FE4";prefs.RingColor="#FF3333";painter.ApplyAppearance(prefs);using(var ring=painter.RenderCapsule(1,quota,"","执行/思考",false,0))Need(SameRegion(initial,ring,left)&&SameRegion(initial,ring,middle)&&!SameRegion(initial,ring,right),"Quota ring color is not independent");
            prefs.HubColor=prefs.CapsuleColor=prefs.RingColor="#FF3333";painter.ApplyAppearance(prefs);using(var all=painter.RenderCapsule(1,quota,"","执行/思考",false,0))Need(!SameRegion(initial,all,left)&&!SameRegion(initial,all,middle)&&!SameRegion(initial,all,right),"Unified color does not reach all three components");
        }
    }
    static object Field(object target,string name){return target.GetType().GetField(name,Private).GetValue(target);}
    static IEnumerable<Control> Controls(Control parent){foreach(Control child in parent.Controls){yield return child;foreach(var nested in Controls(child))yield return nested;}}
    static void CheckAppearanceLayout(Form manager){
        var all=Controls(manager).OfType<Button>().Single(b=>b.Text=="统一配色");var reset=Controls(manager).OfType<Button>().Single(b=>b.Text=="恢复默认");
        var hub=(Control)Field(manager,"hubColorButton");var capsule=(Control)Field(manager,"capsuleColorButton");var ring=(Control)Field(manager,"ringColorButton");var slider=(Control)Field(manager,"capsuleOpacity");
        foreach(var control in new[]{all,reset,hub,capsule,ring,slider})Need(control.Parent.ClientRectangle.Contains(control.Bounds),"Appearance control overflows its row: "+control.Text);
        var action=all.RectangleToScreen(all.ClientRectangle);var colors=hub.RectangleToScreen(hub.ClientRectangle);var opacity=slider.RectangleToScreen(slider.ClientRectangle);
        Need(action.Bottom+5<=colors.Top,"Unified selection and individual colors overlap or have no spacing");Need(colors.Bottom+5<=opacity.Top,"Color controls and opacity slider overlap or have no spacing");
        Need(hub.Bounds.Right+5<=capsule.Bounds.Left&&capsule.Bounds.Right+5<=ring.Bounds.Left,"Individual color controls are crowded horizontally");
    }
    static void Pump(int ms){var clock=Stopwatch.StartNew();while(clock.ElapsedMilliseconds<ms){Application.DoEvents();Thread.Sleep(4);}}
    [STAThread]static int Main(string[] args){string root=args[0],report=args[1];try{Application.EnableVisualStyles();
        var policy=new CodexFollowPolicy();Need(!policy.ShouldExit(true,false,false,0),"No debounce before exiting");Need(!policy.ShouldExit(true,false,false,.4),"Transient hidden window exits manager");Need(!policy.ShouldExit(true,false,true,1),"Import/update is interrupted");Need(policy.ShouldExit(true,false,false,1.2),"Manager does not exit after background debounce");Need(!policy.ShouldExit(true,true,false,2),"Visible Codex triggers exit");Need(!policy.ShouldExit(false,false,false,3),"Disabled setting triggers exit");
        policy=new CodexFollowPolicy();Need(policy.ShouldLaunch(true,false,false,false,0),"Visible Codex does not start manager");Need(!policy.ShouldLaunch(true,false,false,false,1),"Launch retries create duplicates");Need(!policy.ShouldLaunch(true,true,false,false,4),"Running manager is launched twice");Need(!policy.ShouldLaunch(true,false,true,false,5),"Explicit exit immediately restarts manager");Need(!policy.ShouldLaunch(false,false,false,false,6),"Hidden Codex starts manager");Need(policy.ShouldLaunch(true,false,false,false,7),"Next visibility cycle does not restore manager");Need(!policy.ShouldLaunch(true,false,false,true,12),"Update/uninstall relaunches manager");
        var trusted=new HashSet<uint>{(uint)Process.GetCurrentProcess().Id};using(var host=new Form{ShowInTaskbar=false,Opacity=0,ClientSize=new Size(500,450)}){Need(!CodexPresence.VisibleFor(trusted),"Hidden owned fixture is visible");host.Show();Pump(80);Need(CodexPresence.VisibleFor(trusted),"Visible window is not detected");host.WindowState=FormWindowState.Minimized;Pump(80);Need(!CodexPresence.VisibleFor(trusted),"Minimized window is still detected");host.WindowState=FormWindowState.Normal;Pump(80);Need(CodexPresence.VisibleFor(trusted),"Restored window is not detected");Need(!CodexPresence.VisibleFor(new HashSet<uint>{uint.MaxValue}),"Foreign process is accepted");host.Hide();Pump(30);Need(!CodexPresence.VisibleFor(trusted),"Hidden-to-tray fixture is detected");}
        string state=Path.Combine(Path.GetTempPath(),"HubFollowTest-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(state);var prefs=PetPreferences.Load(state);Need(!prefs.FollowCodex&&prefs.CapsuleOpacity==94&&prefs.HubColor=="#4E8FE4","Legacy default behavior changed");prefs.FollowCodex=true;prefs.Scale=109;prefs.CapsuleScale=105;prefs.HubColor="#cc5522";prefs.CapsuleColor="#ee4488";prefs.RingColor="#22ddaa";prefs.CapsuleOpacity=25;prefs.Save(state);prefs=PetPreferences.Load(state);Need(prefs.FollowCodex&&prefs.Scale==109&&prefs.CapsuleScale==105&&prefs.HubColor=="#CC5522"&&prefs.CapsuleColor=="#EE4488"&&prefs.RingColor=="#22DDAA"&&prefs.CapsuleOpacity==25,"New settings do not round-trip");Need(CodexFollow.Enabled(state),"Lightweight watcher cannot read setting");prefs.CapsuleOpacity=999;prefs.CapsuleColor="bad color";prefs.Save(state);prefs=PetPreferences.Load(state);Need(prefs.CapsuleOpacity==100&&prefs.CapsuleColor=="#4E8FE4","Invalid appearance preferences are not bounded");
        string fakeRoot=Path.Combine(state,"app");using(CodexFollow.Suspend(fakeRoot,state)){var sent=new Thread(()=>CodexFollow.ManualExit(fakeRoot,state));sent.IsBackground=true;sent.Start();Pump(100);var name=typeof(CodexFollow).GetMethod("Name",BindingFlags.NonPublic|BindingFlags.Static);string signalName=(string)name.Invoke(null,new object[]{"Manual",fakeRoot,state}),ackName=(string)name.Invoke(null,new object[]{"ManualAck",fakeRoot,state});using(var signal=EventWaitHandle.OpenExisting(signalName))using(var ack=EventWaitHandle.OpenExisting(ackName)){Need(signal.WaitOne(0),"Manual pause is lost before watcher readiness");ack.Set();}Need(sent.Join(2000),"Manual pause acknowledgement does not release normal exit");}
        string legacy=Path.Combine(state,"old-appearance");Directory.CreateDirectory(legacy);File.WriteAllText(Path.Combine(legacy,"pet-settings.json"),"{\"RingColor\":\"#FF3333\",\"CapsuleColor\":\"#117744\",\"CapsuleOpacity\":64,\"Scale\":109,\"FollowCodex\":true}");var migrated=PetPreferences.Load(legacy);Need(migrated.HubColor=="#FF3333"&&migrated.CapsuleColor=="#117744"&&migrated.CapsuleOpacity==64&&migrated.Scale==109&&migrated.FollowCodex,"Old colors, opacity or settings are lost during migration");
        int solidAlpha,clearAlpha;using(var painter=new PetPainter(root)){CheckColors(painter);var quota=new PetQuotaSnapshot{Short=new PetQuotaWindow{Remaining=100}};prefs.CapsuleColor="#EE4488";prefs.CapsuleOpacity=100;painter.ApplyAppearance(prefs);using(var solid=painter.RenderCapsule(1,quota,"","执行/思考",false,0)){solidAlpha=solid.GetPixel(130,13).A;Need(solid.GetPixel(130,13).R>solid.GetPixel(130,13).B,"Capsule color does not change");}prefs.CapsuleOpacity=0;painter.ApplyAppearance(prefs);using(var clear=painter.RenderCapsule(1,quota,"","执行/思考",false,0)){clearAlpha=clear.GetPixel(130,13).A;Need(clearAlpha==0&&solidAlpha==255,"Opacity input does not affect middle capsule");int text=0;for(int y=15;y<36;y++)for(int x=88;x<210;x++){var p=clear.GetPixel(x,y);if(p.A>200&&p.R>180&&p.G>180&&p.B>180)text++;}Need(text>30,"Lower opacity dims capsule text");}foreach(string label in new[]{"100%","99%","1%","<1%","—"}){var b=painter.QuotaLabelBounds(label);Need(b.Width*b.Width+b.Height*b.Height<28.3*28.3&&Math.Abs(b.Left+b.Width/2-20)<.02,"Larger ring text does not fit or is not centered");}}
        using(var manager=(Form)Activator.CreateInstance(typeof(Manager),Private,null,new object[]{false},null)){manager.Opacity=0;manager.Show();typeof(Manager).GetMethod("Navigate",Private).Invoke(manager,new object[]{"pets"});Pump(100);CheckAppearanceLayout(manager);var buttons=Controls(manager).OfType<Button>().Select(b=>b.Text).ToArray();Need(!buttons.Contains("打招呼")&&!buttons.Contains("随机动作"),"Removed action buttons remain");Need(buttons.Contains("刷新真实额度")&&buttons.Contains("互动与动画设置"),"Required settings buttons are missing");var follow=(CheckBox)Field(manager,"petFollowCodex");follow.Checked=true;Need(((PetController)Field(manager,"pets")).Preferences.FollowCodex,"Follow checkbox does not save");var controller=(PetController)Field(manager,"pets");var opacity=(OpacitySlider)Field(manager,"capsuleOpacity");opacity.Value=35;Need(controller.Preferences.CapsuleOpacity==35&&((Label)Field(manager,"capsuleOpacityValue")).Text=="35%","Opacity slider does not preview and display its value");typeof(Manager).GetMethod("CommitPetOpacity",Private).Invoke(manager,null);Need(PetPreferences.Load((string)Field(manager,"stateDirectory")).CapsuleOpacity==35,"Opacity slider does not persist after interaction");Need(opacity.Minimum==0&&opacity.Maximum==100,"Opacity slider range changed");Need(buttons.Contains("统一配色")&&buttons.Contains("左侧按钮")&&buttons.Contains("中间胶囊")&&buttons.Contains("右侧圆环"),"Unified or individual color controls are missing");var colorMethod=typeof(Manager).GetMethod("ApplyPetColor",Private);colorMethod.Invoke(manager,new object[]{PetColorTarget.All,"#4466CC"});Need(controller.Preferences.HubColor=="#4466CC"&&controller.Preferences.CapsuleColor=="#4466CC"&&controller.Preferences.RingColor=="#4466CC","Unified selection does not save three colors");colorMethod.Invoke(manager,new object[]{PetColorTarget.Hub,"#FF3300"});Need(controller.Preferences.HubColor=="#FF3300"&&controller.Preferences.CapsuleColor=="#4466CC"&&controller.Preferences.RingColor=="#4466CC","Individual Hub choice changes other colors");colorMethod.Invoke(manager,new object[]{PetColorTarget.Capsule,"#00CC77"});Need(controller.Preferences.HubColor=="#FF3300"&&controller.Preferences.CapsuleColor=="#00CC77"&&controller.Preferences.RingColor=="#4466CC","Individual capsule choice changes other colors");colorMethod.Invoke(manager,new object[]{PetColorTarget.Ring,"#AA2288"});Need(controller.Preferences.HubColor=="#FF3300"&&controller.Preferences.CapsuleColor=="#00CC77"&&controller.Preferences.RingColor=="#AA2288","Individual ring choice changes other colors");Need(Controls(manager).Any(c=>c.Text=="胶囊与圆环"),"Bottom appearance palette is missing");
            var target=(Manager)manager;var tick=typeof(Manager).GetMethod("CheckFollowCodex",Private);Pump(2100);tick.Invoke(manager,null);Need(!manager.IsDisposed,"Explicit settings launch without Codex cannot be configured");typeof(Manager).GetField("followObservedVisible",Private).SetValue(manager,true);target.ImportingWallpapers=true;tick.Invoke(manager,null);Pump(900);tick.Invoke(manager,null);Need(!manager.IsDisposed,"Follow stopped an active wallpaper import");target.ImportingWallpapers=false;EnableWindow(manager.Handle,false);tick.Invoke(manager,null);Need(!manager.IsDisposed&&manager.Enabled,"Native common dialog owner was not protected");EnableWindow(manager.Handle,true);tick.Invoke(manager,null);Need(manager.IsDisposed,"Manager did not exit normally after protected work completed");}
        File.WriteAllText(report,new JavaScriptSerializer().Serialize(new{pass=true,checks,legacySettingsPreserved=true,automaticExitAndResume=true,manualExitRespected=true,maintenanceBlocksRelaunch=true,ownedWindowMinimizeRestore=true,codexNotManipulated=true,removedPageActions=true,independentColors=true,unifiedThreeColors=true,leftCircleTinted=true,opacitySlider=true,oldAppearanceMigrated=true,opacityPreservesText=true,largerRingTextFits=true,solidAlpha,clearAlpha,realRegistrationChanged=false}));return 0;
